function home(){const recent=done().slice(-5).reverse();return heading('أهلًا بك في نَوى.','مكان واحد لموسيقاك، من أول تنزيل إلى آخر نغمة.',`<button class="secondary" data-action="import">${icon('plus')}أضف من جهازك</button><button class="secondary" data-action="import-folder">إضافة مجلد</button>`)+searchForm()+`<div class="hero"><div class="hero-copy"><h1>كل موسيقاك،<br>أقرب إليك.</h1><p>اجمع ما تحب، احتفظ بأفضل نسخة متاحة،<br>واسـمع التفاصيل بطريقتك.</p><div class="row"><button class="primary" data-action="${recent.length?'play-latest':'demo'}">${icon('play')}${recent.length?'شغّل من مكتبتك':'جرّب المشغل'}</button><button class="secondary" data-nav="search">ابدأ التنزيل</button></div><span class="hero-note">${recent.length?`${done().length} مسار محفوظ في مكتبتك`:'تجربة صوتية محلية من نَوى، بلا حساب'}</span></div><div class="hero-art" aria-hidden="true"><div class="sleeve"><strong>نَوى</strong><span>First light<br>Sound, in your space.</span></div></div></div><div class="section-head"><h2>13 مصدرًا. بحث متصل.</h2><button class="text-button" data-nav="settings">إدارة المصادر</button></div><div class="source-grid">${providers.map(p=>`<button class="source-card" data-source="${p[0]}"><span class="source-symbol" style="--source-color:${p[2]}">${p[3]}</span><span><strong>${p[1]}</strong><small>${p[4]}</small></span></button>`).join('')}</div><div class="section-head"><h2>آخر ما أضفته</h2><button class="text-button" data-nav="library">المكتبة كاملة</button></div>${recent.length?`<div class="album-grid">${recent.map(albumCard).join('')}</div>`:`<div class="empty"><span class="empty-disc">◉</span><h3>أول أغنية تبدأ الحكاية</h3><p>ألصق رابطًا بالأعلى أو أضف ملفاتك المحلية. ستظهر هنا الأغلفة والنسخ المحفوظة فعلًا.</p></div>`}`}
