function applyCustomColors(){ui.colorSets??={};const colors=ui.colorSets?.[ui.theme]||{};for(const [key,variable] of Object.entries({text:'--ink',muted:'--muted',accent:'--accent',panel:'--panel-solid'})){if(/^#[0-9a-f]{6}$/i.test(colors[key]||''))document.documentElement.style.setProperty(variable,colors[key]);else if(key!=='accent'||!ui.customAccent)document.documentElement.style.removeProperty(variable)}document.body.classList.toggle('custom-background',/^#[0-9a-f]{6}$/i.test(colors.background||''));if(colors.background){document.documentElement.style.setProperty('--user-background',colors.background)}else document.documentElement.style.removeProperty('--user-background');document.body.classList.toggle('custom-panel',/^#[0-9a-f]{6}$/i.test(colors.panel||''));if(colors.panel)document.documentElement.style.setProperty('--user-panel',colors.panel);else document.documentElement.style.removeProperty('--user-panel');if(colors.panel){document.documentElement.style.setProperty('--panel',colors.panel+'aa')}else document.documentElement.style.removeProperty('--panel');document.documentElement.style.setProperty('--motion-duration',ui.motionDuration+'s')}
