async function inspectTrack(id){toast('فحص معلومات الملف من المصدر…');const song=await call('InspectSong',id);if(searchResult){const i=searchResult.tracks.findIndex(t=>t.id===id);if(i>=0)searchResult.tracks[i]=song;if(view==='search')render()}toast(song.codec||song.size?'ظهرت المعلومات التي أتاحها المصدر':'المصدر لم يتيح معلومات قبل التنزيل')}
async function inspectResults(){if(!searchResult)return;const tracks=(filter.startsWith('source:')?searchResult.tracks.filter(t=>t.provider===filter.slice(7)):searchResult.tracks).slice(0,limit);let next=0,complete=0;toast(`فحص ${tracks.length} نتيجة؛ قد يستغرق وقتًا`);await Promise.all([0,1].map(async()=>{while(next<tracks.length){const track=tracks[next++];try{const song=await call('InspectSong',track.id);const i=searchResult.tracks.findIndex(t=>t.id===song.id);if(i>=0)searchResult.tracks[i]=song}catch{}complete++;if(view==='search')render()}}));toast(`اكتمل فحص ${complete} نتيجة؛ المعلومات غير المتاحة تُترك فارغة`)}
function lyricsSettings(){const p=snapshot.preferences;return `<div class="settings-grid" style="margin-top:20px"><section class="settings-panel"><h3>مصادر الكلمات والتوقيت</h3><p>يُقرأ الملف المحلي والكاش أولًا. عند الجلب، نفضّل التوقيت الصريح للكلمات، ثم السطور، ثم النص. تُستخدم المصادر المفعّلة فقط وتُحفظ أفضل نتيجة مطابقة محليًا.</p>${lyricSources.filter(p=>p[0]!=='auto').map(([id,name])=>`<label class="check-line"><input type="checkbox" data-lyric-provider="${id}" ${(p.lyricProviders||[]).includes(id)?'checked':''}>${name}</label>`).join('')}<label class="field" for="mxm-key">Musixmatch API key · صلاحية Subtitles</label><input id="mxm-key" type="password" autocomplete="off" placeholder="${snapshot.musixmatchConfigured?'مفتاح محفوظ بأمان':'اختياري؛ يحتاج تصريحًا من Musixmatch'}" style="width:100%"><div class="row"><button class="quiet" data-action="save-mxm">حفظ المفتاح بأمان</button><button class="quiet" data-action="cache-lyrics">حفظ كلمات المكتبة</button></div><p class="note">توفر بعض المصادر يعتمد على البلد والصلاحيات؛ لا تُستخدم ملفات TXT كتوقيت مصطنع.</p></section><section class="settings-panel"><h3>مطابقة التوقيت من الصوت · محلي</h3><p class="notice">تبدأ المطابقة من صفحة الكلمات عندما تختار «اضبط التوقيت الآن». توقيت المصدر وإزاحتك اليدوية يبقيان محفوظين.</p><label class="field" for="alignment-language">لغة الكلمات</label><select id="alignment-language">${[['auto','تلقائي'],['ar','العربية'],['en','English'],['fr','Français'],['es','Español'],['de','Deutsch'],['ru','Русский'],['ja','日本語'],['ko','한국어'],['zh','中文'],['hi','हिन्दी']].map(([id,n])=>`<option value="${id}" ${(p.alignmentLanguage||'auto')===id?'selected':''}>${n}</option>`).join('')}</select><p class="note">${snapshot.alignment?.ready?'محرك المزامنة والنموذج جاهزان بلا إنترنت.':'يتطلب مجلد tools/aligner وملف النموذج المرفق.'} تُحلل الكلمات بالاعتماد على الصوت، وتُحفظ نتيجة تحتوي توقيت كل كلمة. النتائج غير المطمئنة تُعرض للمراجعة وتحفظ الأصل؛ لا يوجد ضمان صفر أخطاء مع الغناء والريمكسات.</p><button class="primary" data-action="save-settings">حفظ إعدادات الكلمات</button></section></div>`}
function alignmentWidget(){const a=snapshot.alignment;if(!a||a.taskId!==current?.id)return '';if(a.running)return `<div class="notice alignment-notice"><span class="spinner"></span><span>${esc(a.phase)} · ${Math.round(a.progress*100)}%</span><button class="quiet" data-action="cancel-align">إلغاء التحليل</button></div>`;if(a.error)return `<div class="notice warning">${esc(a.error)}</div>`;if(a.report?.accepted)return `<div class="notice alignment-notice"><span>${ui.language==='en'?'Timing accepted by you · saved locally':'توقيت معتمد باختيارك · محفوظ محليًا'}</span><button class="quiet" data-action="preview-alignment">${ui.language==='en'?'Review timing':'مراجعة التوقيت'}</button></div>`;if(a.report)return `<div class="notice alignment-notice"><span>${a.report.needsReview?'توقيت مرشح يحتاج مراجعة':'حُفظ توقيت الكلمات محليًا'} · كلمات بتوقيت صالح: ${Math.round(a.report.coverage*100)}% · مؤشر النموذج: ${Math.round(a.report.meanProbability*100)}%<small style="display:block">هذه مؤشرات آلية، وليست ضمانًا للدقة.</small><small style="display:block">${a.report.refined?'تدقيق حدود الكلمات · بحث بخطوة 20 مللي ثانية':'مطابقة أولية تحتاج مراجعة'} · الحروف حركة بصرية داخل مدة الكلمة.</small></span><button class="quiet" data-action="preview-alignment">مراجعة</button>${a.report.needsReview?'<button class="secondary" data-action="apply-alignment">اعتماد بعد المراجعة</button>':''}</div>`;return ''}
async function showAlignmentPreview(){const a=snapshot.alignment;if(!a?.candidate||!current)return;const id=current.id;try{const result=await call('GetAlignmentPreview',id);if(current?.id!==id)return;modal(`<h2>توقيت محلل من الصوت</h2><p>${esc(result.report?.note||'راجع التوقيت قبل اعتماده')}</p><p>اضغط كلمة للانتقال لبدايتها، ثم راجع التوقيت قبل الحفظ.</p><div class="alignment-words" data-user-content>${result.lines.map(line=>`<div dir="auto">${line.words.map(w=>`<button class="quiet alignment-word" data-action="seek-alignment-word" data-start="${Number(w.start)}" dir="auto"><strong>${esc(w.text)}</strong><small dir="ltr">${Number(w.start).toFixed(3)} → ${Number(w.end).toFixed(3)}</small></button>`).join('')}</div>`).join('')}</div><pre>${esc(a.candidate)}</pre><button class="primary" data-action="apply-alignment">اعتماد وحفظ محلي</button>`)}catch(e){toast(String(e))}}
function textDirection(text){for(const c of String(text)){if(/\p{Letter}/u.test(c))return /[\u0590-\u08ff\ufb1d-\ufdff\ufe70-\ufeff\u{10800}-\u{10fff}\u{1e800}-\u{1edff}]/u.test(c)?'rtl':'ltr'}return 'ltr'}
function joiningScript(text){return /[\p{Script=Arabic}\p{Script=Syriac}\p{Script=Thaana}\p{Script=Nko}\p{Script=Devanagari}\p{Script=Bengali}\p{Script=Gurmukhi}\p{Script=Gujarati}\p{Script=Oriya}\p{Script=Tamil}\p{Script=Telugu}\p{Script=Kannada}\p{Script=Malayalam}\p{Script=Sinhala}\p{Script=Khmer}\p{Script=Myanmar}]/u.test(text)}
function lyricTokens(text,aligned=[]){if(aligned.length){let cursor=0,tokens=[];for(const w of aligned){const body=String(w.text||'').trim();if(!body)continue;const at=text.indexOf(body,cursor);if(at<0){tokens=[];break}if(at>cursor)tokens.push({text:text.slice(cursor,at),start:-1,end:-1});tokens.push({...w,text:body});cursor=at+body.length}if(tokens.length){if(cursor<text.length)tokens.push({text:text.slice(cursor),start:-1,end:-1});return tokens}}return text.split(/(\s+)/).filter(Boolean).map(text=>({text,start:-1,end:-1}))}
const lyricGraphemeSegmenter=typeof Intl.Segmenter==='function'?new Intl.Segmenter(undefined,{granularity:'grapheme'}):null;
function renderDirectionalText(text,aligned=[],style=ui.lyricStyle){
 // Canvas keeps real timed data independently; its hidden DOM needs logical text only.
 if(style?.startsWith('verci-')){const direction=textDirection(text),arabic=/\p{Script=Arabic}/u.test(text);return `<span aria-hidden="true" class="lyric-content lyric-content-compact ${arabic?'arabic':'latin'}" dir="${direction}">${esc(text)}</span><span class="sr-only">${esc(text)}</span>`}

 const words=lyricTokens(text,aligned).map(word=>({...word,graphemes:lyricGraphemeSegmenter?[...lyricGraphemeSegmenter.segment(word.text)].map(item=>item.segment):[...word.text]}));
 const arabic=/\p{Script=Arabic}/u.test(text),direction=textDirection(text),total=words.reduce((sum,word)=>sum+word.graphemes.length,0);let character=0;
 return `<span aria-hidden="true" class="lyric-content ${arabic?'arabic':'latin'}" dir="${direction}">${words.map((word,index)=>{if(/^\s+$/.test(word.text)){character+=word.graphemes.length;return esc(word.text)}const joined=joiningScript(word.text);return `<span class="lyric-word ${joined?'joined':'separate'}" dir="${textDirection(word.text)}" data-start="${Number.isFinite(word.start)?word.start:-1}" data-end="${Number.isFinite(word.end)?word.end:-1}" data-timing-origin="${word.origin||'source'}" style="--wi:${index/Math.max(1,words.length)}">${word.graphemes.map(characterText=>`<span class="lyric-char" style="--ci:${character++/Math.max(1,total)}">${esc(characterText)}</span>`).join('')}</span>`}).join('')}</span><span class="sr-only">${esc(text)}</span>`;
}
let visualTimingCache=null;
function lyricTimingPlan(){const length=duration();if(!visualTimingCache||visualTimingCache.lines!==lyricData||visualTimingCache.words!==lyricWordLines||visualTimingCache.duration!==length){const value=window.NawaTiming?window.NawaTiming.plan(lyricData,lyricWordLines,length):{rows:lyricWordLines,kind:lyricWordLines.length?'word':'line'};visualTimingCache={lines:lyricData,words:lyricWordLines,duration:length,value}}return visualTimingCache.value}
function lyricTimingRows(){return lyricTimingPlan().rows}
let lyricAlignedRowsSource=null,lyricAlignedRows=[];
function renderLyricText(line,index){
 const displayRows=lyricTimingRows();if(lyricAlignedRowsSource!==displayRows){lyricAlignedRowsSource=displayRows;lyricAlignedRows=displayRows.filter(row=>Number.isFinite(row.start)).slice().sort((a,b)=>a.start-b.start)}
 const time=Number(line.time);let low=0,high=lyricAlignedRows.length;
 while(low<high){const mid=(low+high)>>>1;if(lyricAlignedRows[mid].start<time)low=mid+1;else high=mid}
 const candidates=[lyricAlignedRows[low-1],lyricAlignedRows[low]].filter(row=>row&&Math.abs(row.start-time)<.25).sort((a,b)=>Math.abs(a.start-time)-Math.abs(b.start-time));
 return renderDirectionalText(line.text,candidates[0]?.words||[]);
}
function updateWordTiming(pos){
 if(window.madarLyricClock){window.madarLyricClock.updateWords(pos);return}
 if(!lyricWordLines.length)return;const active=$('.lyric-line.current');if(!active)return;
 for(const word of $$('.lyric-word',active)){const start=Number(word.dataset.start),end=Number(word.dataset.end);if(start<0||end<=start)continue;word.classList.toggle('sung',pos>=end);word.classList.toggle('singing',pos>=start&&pos<end);const progress=Math.min(1,Math.max(0,(pos-start)/(end-start))),chars=$$('.lyric-char',word);chars.forEach((element,i)=>element.classList.toggle('sung',i/chars.length<progress))}
}


const translationLanguages=[['ar','العربية'],['en','English'],['fr','Français'],['es','Español'],['de','Deutsch'],['ru','Русский'],['ja','日本語'],['ko','한국어'],['zh','中文'],['hi','हिन्दी'],['tr','Türkçe'],['pt','Português'],['it','Italiano'],['fa','فارسی'],['ur','اردو'],['id','Indonesia'],['nl','Nederlands'],['uk','Українська']];
function translationControls(){return `<section class="translation-controls" aria-label="ترجمة الكلمات"><div class="translation-options"><label class="check-line"><input id="translation-enabled" type="checkbox" ${ui.translationEnabled?'checked':''}>ترجمة تحت الأصل</label><label>إلى <select id="translation-target" aria-label="لغة الترجمة">${translationLanguages.map(([id,n])=>`<option value="${id}" ${ui.translationTarget===id?'selected':''}>${n}</option>`).join('')}</select></label><label>لغة الأصل <select id="translation-source" aria-label="لغة الكلمات الأصلية"><option value="auto" ${ui.translationSource==='auto'?'selected':''}>تلقائي</option>${translationLanguages.map(([id,n])=>`<option value="${id}" ${ui.translationSource===id?'selected':''}>${n}</option>`).join('')}</select></label><label class="check-line"><input id="translation-auto" type="checkbox" ${ui.translationAuto?'checked':''}>ترجمة تلقائية</label><button class="quiet" data-action="translate-now">إعادة الترجمة</button><button class="text-button" data-action="edit-translation">تصحيح وحفظ</button></div><div id="translation-status" class="note" role="status">محرك محلي · العربية و17 لغة أخرى · تُحفظ الترجمات مع الكلمات دون إنترنت.</div><p class="translation-note">الترجمة الآلية قد تخطئ في الشعر واللهجات. يمكنك تصحيح كل سطر وحفظه؛ تبقى الكلمات الأصلية محفوظة.</p></section>`}
function translationMarkup(line,i){const row=translationData?.lines?.[i];return ui.translationEnabled&&translationData?.exists&&!translationData?.sameLanguage&&row?.original===line.text?`<span class="lyric-translation" dir="${textDirection(row.text)}" lang="${esc(ui.translationTarget)}">${renderDirectionalText(row.text)}</span>`:''}
function paintTranslations(){if(view!=='lyrics')return;const stage=$('#lyric-stage');if(!stage)return;$$('.lyric-translation',stage).forEach(el=>el.remove());if(!ui.translationEnabled){window.madarVerci?.sync();return;}$$('.lyric-line',stage).forEach((el,i)=>{if(lyricData[i])el.insertAdjacentHTML('beforeend',translationMarkup(lyricData[i],i))});window.madarVerci?.sync()}
async function loadTranslation(automatic=false){if(!current||view!=='lyrics'||!lyricData.length)return;const version=++translationVersion,id=current.id,target=ui.translationTarget,source=ui.translationSource;try{const r=await call('GetTranslation',id,target,source,automatic&&ui.translationAuto&&ui.translationEnabled);if(version!==translationVersion||current?.id!==id||view!=='lyrics'||target!==ui.translationTarget||source!==ui.translationSource)return;translationData=r;paintTranslations();const label=r.status+(r.exists&&r.source?' · لغة الأصل: '+(translationLanguages.find(x=>x[0]===r.source)?.[1]||r.source):'');for(const node of [$('#translation-status'),$('#translation-summary')])if(node)node.textContent=label;pollTranslation()}catch(e){if(version===translationVersion)for(const node of [$('#translation-status'),$('#translation-summary')])if(node)node.textContent=e.message||String(e)}}
function pollTranslation(){if(view!=='lyrics')return;const t=snapshot.translation||{},status=$('#translation-status'),summary=$('#translation-summary'),relevant=t.taskId===current?.id&&t.target===ui.translationTarget;if(t.running&&relevant){if(status)status.innerHTML=`<span class="translation-progress"><i class="spinner"></i>${esc(t.phase)} · ${Math.round((t.progress||0)*100)}% <button class="text-button" data-action="cancel-translation">إيقاف</button></span>`;if(summary)summary.textContent=`${t.phase} · ${Math.round((t.progress||0)*100)}%`}else if(t.error&&relevant&&!translationData?.exists){if(status)status.textContent=t.error;if(summary)summary.textContent=t.error}const sig=JSON.stringify([t.revision,t.running,t.taskId,t.target]);if(sig!==translationSignature){translationSignature=sig;if(lyricData.length&&(!t.running||t.taskId!==current?.id||t.target!==ui.translationTarget))loadTranslation(false)}}
function editTranslation(){if(!current||!lyricData.length){toast('أضف الكلمات أولًا');return}if(!translationData?.originalHash){toast('انتظر تجهيز الكلمات ثم أعد المحاولة');return}modal(`<h2>تصحيح الترجمة · ${esc(translationLanguages.find(x=>x[0]===ui.translationTarget)?.[1]||ui.translationTarget)}</h2><p>كل حقل مقابل سطره الأصلي. يحفظ التصحيح محليًا بهذه اللغة.</p><div class="translation-editor" data-original-hash="${esc(translationData.originalHash)}" data-task="${esc(current.id)}" data-target="${esc(ui.translationTarget)}" data-source="${esc(ui.translationSource)}">${lyricData.map((line,i)=>`<label><span dir="auto">${esc(line.text)}</span><textarea data-translation-row="${i}" rows="2" dir="auto" aria-label="ترجمة السطر ${i+1}">${esc(translationData.lines?.[i]?.text||'')}</textarea></label>`).join('')}</div><button class="primary" data-action="save-translation">حفظ التصحيح</button>`)}
async function saveTranslationEdit(){const editor=$('.translation-editor');if(!editor)return;const rows=$$('[data-translation-row]',editor).map(x=>x.value.trim());await call('SaveTranslation',editor.dataset.task,editor.dataset.target,editor.dataset.source,editor.dataset.originalHash,rows);$('#modal').close();await loadTranslation(false);toast('حُفظت الترجمة المصححة مع الكلمات')}

async function saveTranslationPreferences(){try{const p={...snapshot.preferences,autoTranslate:ui.translationAuto,translationTarget:ui.translationTarget,translationSource:ui.translationSource};await call('SetPreferences',p);snapshot.preferences=p}catch(e){toast(e.message||e)}}

async function previewTask(id,forceDecode=false){const request=++previewRequest;toast('تجهيز البث من المصدر…');const p=await call('PreparePreview',id,forceDecode);if(request!==previewRequest)return;ensureGraph();await graph.ctx.resume();current={id:p.song.id,song:p.song,preview:true,quality:p.quality||{},decoded:p.decoded,status:'preview',log:[]};ui.lyricOffset=Number(ui.lyricOffsets?.[id]||0);audio.src=p.url;applyFX();await audio.play();if(searchResult){const i=searchResult.tracks.findIndex(x=>x.id===p.song.id);if(i>=0)searchResult.tracks[i]=p.song}updateNow();if(['search','lyrics','player'].includes(view))render();toast(p.notice||'بث مباشر قبل التنزيل');window.madarMetadata?.cachePreview(p.song.id)}
function applyTypography(){for(const [key,variable] of [['lyricFont','--lyric-font'],['translationFont','--translation-font']]){const family=String(ui[key]||'').replace(/["\\]/g,'');if(family)document.documentElement.style.setProperty(variable,'"'+family+'", "Segoe UI", Tahoma, sans-serif');else document.documentElement.style.removeProperty(variable)}}
function lyricFontControls(){const options=value=>`<option value="">خط الواجهة تلقائيًا</option>`+([...new Set([...(value?[value]:[]),...(window.madarGameThemes?.fonts||[]),...installedFonts])]).map(font=>`<option value="${esc(font)}" ${value===font?'selected':''}>${esc(font)}</option>`).join('');return `<section class="lyrics-popup-section"><h3>خطوط جهازك</h3><div class="lyrics-field-grid"><label>خط الكلمات الأصلية<select id="lyric-font" aria-label="خط الكلمات الأصلية">${options(ui.lyricFont)}</select></label><label>خط الترجمة<select id="translation-font" aria-label="خط الترجمة">${options(ui.translationFont)}</select></label></div><p class="note" style="margin-top:12px">اختيار مستقل للأصل والترجمة، مع حفظ تلقائي. الحروف غير المتوفرة في الخط تُعرض بخط بديل يدعمه Windows.</p></section>`}

function shouldAdvanceAfterEnd(){const order=current?.preview?visibleSearch().filter(t=>t.provider!=='spotify').map(t=>t.id):(playOrder.length?playOrder:done().map(t=>t.id));const index=order.indexOf(current?.id);return order.length>1&&(ui.shuffle||(index>=0&&index<order.length-1))}

